package dev.agenttrust.core;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class CampaignBaselineArchivesTest {
 private final ObjectMapper mapper=new ObjectMapper();private final DemoUser user=new DemoUser("reader","unused",UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"viewer");private final UUID baseline=UUID.randomUUID(),agent=UUID.randomUUID(),dataset=UUID.randomUUID();
 private Map<String,Object> record(){return Map.of("id",baseline,"organization_id",user.organizationId(),"project_id",user.projectId(),"agent_version_id",agent,"agent_content_sha256","a".repeat(64),"dataset_version_id",dataset,"dataset_content_sha256","b".repeat(64),"state","succeeded","decision","pass");}
 private Map<String,Object> requirements(){return Map.of("enabled",true,"baselineCampaignId",baseline,"baselineAgentVersionId",agent,"baselineAgentContentSha256","a".repeat(64),"datasetVersionId",dataset,"datasetContentSha256","b".repeat(64));}
 private Map<String,Object> proof(Map<String,Object> record)throws Exception{byte[] bytes=mapper.writeValueAsBytes(Map.of("schemaVersion",2,"kind","campaign-evidence","deploymentAuthority",false,"campaign",record,"childArchives",List.of(Map.of("runId",UUID.randomUUID(),"contentSha256","c".repeat(64),"contentBytes",100,"storageVersion","child-original"))));return Map.of("contentBase64",Base64.getEncoder().encodeToString(bytes),"contentSha256",ArchiveIntegrity.sha256(bytes),"contentBytes",bytes.length,"storageVersion","baseline-original");}
 @Test void signedDescriptorUsesExactOriginalParentAndChildMetadata()throws Exception{var record=record();var proof=proof(record);var result=CampaignBaselineArchives.binding(user,requirements(),record,proof,mapper);assertEquals(baseline,result.get("campaignId"));assertEquals(5,result.size());assertEquals(proof.get("contentSha256"),((Map<?,?>)result.get("campaignArchive")).get("contentSha256"));assertEquals("pass",result.get("evaluationDecision"));}
 @Test void foreignBaselineVersionAndSubstitutedHashAreRejected()throws Exception{var record=record();var proof=proof(record);for(String key:List.of("baselineCampaignId","baselineAgentVersionId","datasetVersionId")){var changed=new HashMap<>(requirements());changed.put(key,UUID.randomUUID());assertThrows(IllegalArgumentException.class,()->CampaignBaselineArchives.binding(user,changed,record,proof,mapper));}var changed=new HashMap<>(proof);changed.put("contentSha256","d".repeat(64));assertThrows(IllegalArgumentException.class,()->CampaignBaselineArchives.binding(user,requirements(),record,changed,mapper));var other=new DemoUser("foreign","unused",UUID.randomUUID(),user.projectId(),user.actorId(),"admin");assertThrows(IllegalArgumentException.class,()->CampaignBaselineArchives.binding(other,requirements(),record,proof,mapper));}
 @Test void rehashedParentCannotSubstituteTheFrozenRecord()throws Exception{var record=record();var changed=new HashMap<>(record);changed.put("decision","block");var proof=proof(changed);assertThrows(IllegalArgumentException.class,()->CampaignBaselineArchives.binding(user,requirements(),record,proof,mapper));}
}
